{
  "files": [
    {
      "path": "_OPS/devnotes-normalize-properties-pass1.ps1",
      "content": "Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

param(
  [switch]$Apply
)

if (-not (Test-Path ".obsidian")) {
  throw "Run this from the DevNotes vault root."
}

$RunMode = if ($Apply) { "APPLY" } else { "PREVIEW" }
$Today = Get-Date -Format "yyyy-MM-dd"
$VaultRoot = (Get-Location).Path
$ReportDir = "_OPS"
$ReportPath = Join-Path $ReportDir "property-normalization-pass1.csv"

if (-not (Test-Path -LiteralPath $ReportDir)) {
  New-Item -ItemType Directory -Force -Path $ReportDir | Out-Null
}

function Get-RelPath {
  param([string]$FullPath)
  return $FullPath.Substring($VaultRoot.Length).TrimStart("\","/")
}

function Convert-ToSlug {
  param([string]$Value)

  if ([string]::IsNullOrWhiteSpace($Value)) {
    return "unknown"
  }

  $slug = $Value.ToLowerInvariant()
  $slug = $slug -replace "&", "and"
  $slug = $slug -replace "[^a-z0-9]+", "-"
  $slug = $slug.Trim("-")

  if ([string]::IsNullOrWhiteSpace($slug)) {
    return "unknown"
  }

  return $slug
}

function Convert-ToTitle {
  param([string]$Value)

  if ([string]::IsNullOrWhiteSpace($Value)) {
    return "Untitled"
  }

  $clean = $Value
  $clean = $clean -replace "\.md$", ""
  $clean = $clean -replace "\.", " "
  $clean = $clean -replace "[-_]+", " "
  $clean = $clean.Trim()

  if ([string]::IsNullOrWhiteSpace($clean)) {
    return "Untitled"
  }

  return (Get-Culture).TextInfo.ToTitleCase($clean.ToLowerInvariant())
}

function Format-YamlScalar {
  param([AllowNull()][string]$Value)

  if ($null -eq $Value -or $Value -eq "") {
    return ""
  }

  $escaped = $Value.Replace('"','\"')
  return '"' + $escaped + '"'
}

function Test-YamlHasKey {
  param(
    [string]$Yaml,
    [string]$Key
  )

  return [regex]::IsMatch($Yaml, "(?m)^\s*$([regex]::Escape($Key))\s*:")
}

function Get-FirstHeading {
  param([string]$Text)

  $m = [regex]::Match($Text, "(?m)^#\s+(?<title>.+?)\s*$")
  if ($m.Success) {
    return $m.Groups["title"].Value.Trim()
  }

  return $null
}

function Get-ProjectFromPath {
  param([string]$RelPath)

  $m = [regex]::Match($RelPath, "^10 PROJECTS[\\/](?<project>[^\\/]+)[\\/]")
  if ($m.Success) {
    return $m.Groups["project"].Value
  }

  return ""
}

function Get-ProjectSection {
  param([string]$RelPath)

  $m = [regex]::Match($RelPath, "^10 PROJECTS[\\/][^\\/]+[\\/](?<section>[^\\/]+)")
  if ($m.Success) {
    return $m.Groups["section"].Value
  }

  return ""
}

function Get-TopDomain {
  param([string]$RelPath)

  if ($RelPath -like "00 ZETTELKASTEN/*") { return "zettelkasten" }
  if ($RelPath -like "10 PROJECTS/*") { return "projects" }
  if ($RelPath -like "20 DOCUMENTATION/*") { return "documentation" }
  if ($RelPath -like "30 DEEP RESEARCH/*") { return "deep-research" }
  if ($RelPath -like "40 TECH STACK/*") { return "tech-stack" }
  if ($RelPath -like "50 REGRETS, CIGARETTES, & NEURAL NETS/*") { return "writing" }
  if ($RelPath -like "90 OBSIDIAN/*") { return "obsidian" }
  return "vault"
}

function Get-DomainFromPath {
  param(
    [string]$RelPath,
    [string]$Project
  )

  if ($Project) {
    $section = Get-ProjectSection $RelPath

    if ($section -eq "00 PROJECT MAP") { return "project" }
    if ($section -eq "10 PRODUCT") { return "product" }
    if ($section -eq "30 ARCHITECTURE") { return "architecture" }
    if ($section -eq "40 FEATURES") { return "features" }
    if ($section -eq "50 AGENT OPS") { return "agent-ops" }
    if ($section -eq "60 EXECUTION") { return "execution" }
    if ($section -eq "70 RESEARCH") { return "research" }
    if ($section -eq "80 LEGAL") { return "legal" }
    if ($section -eq "90 ARCHIVE") { return "archive" }

    $m = [regex]::Match($RelPath, "^10 PROJECTS[\\/][^\\]+[\\/]20 CONTRACTS[\\/](?<domain>[^\\/]+)")
    if ($m.Success) {
      return $m.Groups["domain"].Value
    }

    if ($section -eq "20 CONTRACTS") { return "contracts" }

    return "project"
  }

  return Get-TopDomain $RelPath
}

function Get-TypeFromPath {
  param(
    [string]$RelPath,
    [string]$FileBase,
    [string]$Domain
  )

  if ($RelPath -like "90 OBSIDIAN/OB-Templates/*") { return "template" }
  if ($RelPath -like "90 OBSIDIAN/Dashboards/*") { return "dashboard" }
  if ($RelPath -like "90 OBSIDIAN/Workflows/*") { return "workflow" }
  if ($RelPath -like "90 OBSIDIAN/Contracts/*") { return "standard" }
  if ($FileBase -match "\.contract$" -or $RelPath -like "*/20 CONTRACTS/*") { return "contract" }
  if ($FileBase -match "\.map$" -or $RelPath -like "*/00 PROJECT MAP/*") { return "map" }
  if ($FileBase -match "\.workflow$") { return "workflow" }
  if ($FileBase -match "\.dashboard$") { return "dashboard" }
  if ($FileBase -match "\.legacy$" -or $RelPath -like "*/90 ARCHIVE/*") { return "legacy" }

  if ($Domain -eq "research" -or $RelPath -like "30 DEEP RESEARCH/*") { return "research" }
  if ($Domain -eq "documentation" -or $Domain -eq "tech-stack" -or $RelPath -like "20 DOCUMENTATION/*" -or $RelPath -like "40 TECH STACK/*") { return "reference" }
  if ($Domain -eq "writing" -or $RelPath -like "50 REGRETS, CIGARETTES, & NEURAL NETS/*") { return "writing" }
  if ($Domain -eq "execution") { return "execution" }
  if ($Domain -eq "legal") { return "legal" }
  if ($Domain -eq "architecture") { return "architecture" }
  if ($Domain -eq "product") { return "product" }
  if ($Domain -eq "features") { return "feature" }
  if ($Domain -eq "zettelkasten") { return "capture" }

  return "note"
}

function Get-KindFromTypeAndName {
  param(
    [string]$Type,
    [string]$FileBase
  )

  if ($FileBase -match "\.contract$") { return "contract" }
  if ($FileBase -match "\.map$") { return "map" }
  if ($FileBase -match "\.workflow$") { return "workflow" }
  if ($FileBase -match "\.dashboard$") { return "dashboard" }
  if ($FileBase -match "\.legacy$") { return "legacy" }
  if ($FileBase -match "\.spec$") { return "spec" }
  if ($FileBase -match "\.checklist$") { return "checklist" }
  if ($FileBase -match "\.work-package$") { return "work-package" }
  if ($FileBase -match "\.handoff$") { return "handoff" }

  return $Type
}

function Get-Namespace {
  param(
    [string]$RelPath,
    [string]$FileBase,
    [string]$Project,
    [string]$Domain
  )

  if ($FileBase -match "\.") {
    return $FileBase.ToLowerInvariant()
  }

  $fileSlug = Convert-ToSlug $FileBase

  if ($Project) {
    $projectSlug = Convert-ToSlug $Project
    return "$projectSlug.$Domain.$fileSlug"
  }

  $topDomain = Get-TopDomain $RelPath

  if ($topDomain -eq "obsidian") {
    return "obsidian.$fileSlug"
  }

  return "devnotes.$topDomain.$fileSlug"
}

function Get-Artifact {
  param(
    [string]$Namespace,
    [string]$Project,
    [string]$Domain,
    [string]$Kind,
    [string]$FileBase
  )

  $parts = @($Namespace.Split(".") | Where-Object { $_ })

  if ($parts.Count -ge 3) {
    $start = 2
    $end = $parts.Count - 1

    if ($parts[$parts.Count - 1] -eq $Kind -and $parts.Count -ge 4) {
      $end = $parts.Count - 2
    }

    if ($end -ge $start) {
      return ($parts[$start..$end] -join ".")
    }
  }

  return Convert-ToSlug $FileBase
}

function Get-Status {
  param(
    [string]$RelPath,
    [string]$FileBase,
    [string]$Type
  )

  if ($FileBase -match "\.legacy$" -or $RelPath -like "*/90 ARCHIVE/*") { return "legacy" }
  if ($RelPath -like "00 ZETTELKASTEN/*") { return "draft" }
  if ($Type -eq "template") { return "active" }
  if ($Type -eq "contract" -and $RelPath -like "90 OBSIDIAN/OB-Templates/*") { return "active" }
  return "active"
}

function Get-Authority {
  param(
    [string]$Type,
    [string]$Status,
    [string]$RelPath
  )

  if ($Status -eq "legacy") { return "legacy" }
  if ($Type -in @("contract","map","standard","workflow")) { return "source-of-truth" }
  if ($Type -in @("reference","research","writing","template","dashboard")) { return "reference" }
  if ($Type -in @("capture","execution")) { return "working-note" }
  return "reference"
}

function Get-Parent {
  param(
    [string]$Project,
    [string]$Type,
    [string]$Namespace,
    [string]$RelPath
  )

  if ($Namespace -eq "devnotes.home") { return "" }
  if ($Namespace -eq "devnotes.projects.map") { return "[[devnotes.home]]" }

  if ($Project) {
    $projectSlug = Convert-ToSlug $Project
    if ($Namespace -eq "$projectSlug.project.map") {
      return "[[devnotes.projects.map]]"
    }

    return "[[$projectSlug.project.map]]"
  }

  if ($RelPath -like "00 ZETTELKASTEN/*") { return "[[devnotes.zettelkasten.map]]" }
  if ($RelPath -like "20 DOCUMENTATION/*") { return "[[devnotes.documentation.map]]" }
  if ($RelPath -like "30 DEEP RESEARCH/*") { return "[[devnotes.deep-research.map]]" }
  if ($RelPath -like "40 TECH STACK/*") { return "[[devnotes.tech-stack.map]]" }
  if ($RelPath -like "50 REGRETS, CIGARETTES, & NEURAL NETS/*") { return "[[devnotes.regrets-cigarettes-neural-nets.map]]" }
  if ($RelPath -like "90 OBSIDIAN/*") { return "[[obsidian.system.map]]" }

  return "[[devnotes.home]]"
}

function Get-Tags {
  param(
    [string]$Project,
    [string]$Domain,
    [string]$Type,
    [string]$Status,
    [string]$Kind
  )

  $tags = New-Object System.Collections.Generic.List[string]

  if ($Project) {
    $tags.Add("projects/$(Convert-ToSlug $Project)")
  }

  if ($Domain) {
    $tags.Add("domains/$Domain")
  }

  if ($Type) {
    $tags.Add("types/$Type")
  }

  if ($Kind -and $Kind -ne $Type) {
    $tags.Add("kinds/$Kind")
  }

  if ($Status) {
    $tags.Add("status/$Status")
  }

  return @($tags | Select-Object -Unique)
}

function Get-MetaForFile {
  param(
    [string]$RelPath,
    [string]$Text,
    [System.IO.FileInfo]$File
  )

  $fileBase = [System.IO.Path]::GetFileNameWithoutExtension($File.Name)
  $heading = Get-FirstHeading $Text
  $title = if ($heading) { $heading } else { Convert-ToTitle $fileBase }

  $project = Get-ProjectFromPath $RelPath
  $scope = if ($project) { "project" } elseif ($RelPath -like "90 OBSIDIAN/*") { "vault" } else { "reference" }
  $domain = Get-DomainFromPath $RelPath $project
  $type = Get-TypeFromPath $RelPath $fileBase $domain
  $kind = Get-KindFromTypeAndName $type $fileBase
  $namespace = Get-Namespace $RelPath $fileBase $project $domain
  $artifact = Get-Artifact $namespace $project $domain $kind $fileBase
  $status = Get-Status $RelPath $fileBase $type
  $authority = Get-Authority $type $status $RelPath
  $parent = Get-Parent $project $type $namespace $RelPath
  $tags = Get-Tags $project $domain $type $status $kind

  return [ordered]@{
    title = $title
    type = $type
    scope = $scope
    project = $project
    domain = $domain
    artifact = $artifact
    kind = $kind
    namespace = $namespace
    status = $status
    authority = $authority
    parent = $parent
    depends_on = @()
    supersedes = @()
    tags = $tags
    created = $File.CreationTime.ToString("yyyy-MM-dd")
    updated = $Today
  }
}

function New-YamlLines {
  param([hashtable]$Meta)

  $lines = New-Object System.Collections.Generic.List[string]

  $lines.Add("title: $(Format-YamlScalar $Meta.title)")
  $lines.Add("type: $($Meta.type)")
  $lines.Add("scope: $($Meta.scope)")
  if ($Meta.project) { $lines.Add("project: $($Meta.project)") } else { $lines.Add("project:") }
  $lines.Add("domain: $($Meta.domain)")
  $lines.Add("artifact: $($Meta.artifact)")
  $lines.Add("kind: $($Meta.kind)")
  $lines.Add("namespace: $($Meta.namespace)")
  $lines.Add("status: $($Meta.status)")
  $lines.Add("authority: $($Meta.authority)")
  if ($Meta.parent) { $lines.Add("parent: $(Format-YamlScalar $Meta.parent)") } else { $lines.Add("parent:") }
  $lines.Add("depends_on: []")
  $lines.Add("supersedes: []")
  $lines.Add("tags:")
  foreach ($tag in $Meta.tags) {
    $lines.Add("  - $tag")
  }
  $lines.Add("created: $($Meta.created)")
  $lines.Add("updated: $($Meta.updated)")

  return @($lines)
}

function Add-OrCompleteFrontmatter {
  param(
    [string]$Text,
    [hashtable]$Meta
  )

  $allLines = New-YamlLines $Meta

  $frontmatterMatch = [regex]::Match($Text, "(?s)^---\r?\n(?<yaml>.*?)\r?\n---(?<rest>.*)$")

  if (-not $frontmatterMatch.Success) {
    $yaml = ($allLines -join "`n")
    return "---`n$yaml`n---`n`n$Text"
  }

  $yamlExisting = $frontmatterMatch.Groups["yaml"].Value
  $rest = $frontmatterMatch.Groups["rest"].Value
  $missing = New-Object System.Collections.Generic.List[string]

  $keyBuffer = $null

  foreach ($line in $allLines) {
    if ($line -match "^(?<key>[A-Za-z0-9_-]+):") {
      $key = $Matches.key

      if (-not (Test-YamlHasKey $yamlExisting $key)) {
        $missing.Add($line)
        $keyBuffer = $key
      } else {
        $keyBuffer = $null
      }

      continue
    }

    if ($keyBuffer) {
      $missing.Add($line)
    }
  }

  if ($missing.Count -eq 0) {
    return $Text
  }

  $yamlNew = $yamlExisting.TrimEnd() + "`n" + ($missing -join "`n")
  return "---`n$yamlNew`n---$rest"
}

$files = Get-ChildItem -LiteralPath "." -Recurse -File -Filter "*.md" |
  Where-Object {
    $rel = Get-RelPath $_.FullName

    $rel -notlike ".obsidian/*" -and
    $rel -notlike ".git/*" -and
    $rel -notlike ".agent-logs/*" -and
    $rel -notlike "_OPS/*" -and
    $rel -notlike "90 OBSIDIAN/OB-Templates/*"
  }

$report = New-Object System.Collections.Generic.List[object]
$changed = 0
$unchanged = 0

foreach ($file in $files) {
  $rel = Get-RelPath $file.FullName
  $text = Get-Content -Raw -LiteralPath $file.FullName
  $meta = Get-MetaForFile $rel $text $file
  $newText = Add-OrCompleteFrontmatter $text $meta
  $willChange = ($newText -ne $text)

  if ($willChange) {
    $changed++

    if ($Apply) {
      $newText | Set-Content -LiteralPath $file.FullName -Encoding UTF8
      Write-Host "NORMALIZE $rel" -ForegroundColor Cyan
    } else {
      Write-Host "WOULD NORMALIZE $rel" -ForegroundColor Yellow
    }
  } else {
    $unchanged++
  }

  $report.Add([pscustomobject]@{
    path = $rel
    title = $meta.title
    type = $meta.type
    scope = $meta.scope
    project = $meta.project
    domain = $meta.domain
    artifact = $meta.artifact
    kind = $meta.kind
    namespace = $meta.namespace
    status = $meta.status
    authority = $meta.authority
    parent = $meta.parent
    changed = $willChange
  })
}

$report | Export-Csv -NoTypeInformation -Encoding UTF8 -Path $ReportPath

Write-Host ""
Write-Host "PROPERTY NORMALIZATION PASS 1: $RunMode" -ForegroundColor Green
Write-Host "Files scanned: $($files.Count)"
Write-Host "Changed: $changed"
Write-Host "Unchanged: $unchanged"
Write-Host "Report: $ReportPath"
Write-Host ""
git status --short
"
    }
  ]
}

