function Invoke-DevMenu {
  if (-not (Get-Command fzf -ErrorAction SilentlyContinue)) {
    Write-Host "[menu] fzf.exe not found." -ForegroundColor Yellow
    return
  }

  $items = @(
    "FILES      Open file picker in VS Code"
    "FILES      Generate tree.txt from current folder"
    "FILES      Print tree with files"
    "GIT        Status"
    "GIT        Add all"
    "GIT        Commit"
    "GIT        Push"
    "WSL        Open WSL here"
    "WSL        List WSL distros"
    "NETWORK    List listening ports"
    "NETWORK    Check port"
    "NETWORK    Kill process by port"
    "NETWORK    Kill process by PID"
    "NETWORK    Test github.com"
    "NETWORK    DNS github.com"
    "SYSTEM     Dev rig check"
    "SYSTEM     Show PATH"
    "SYSTEM     Edit PowerShell profile"
    "SYSTEM     Reload PowerShell profile"
  )

  $choice = $items | fzf --height 70% --border --prompt "dev menu > " --header "Ctrl+t Dev Menu | arrows select | enter run | esc cancel"

  switch -Wildcard ($choice) {
    "FILES*Open file picker*" {
      $file = Get-ChildItem -Recurse -File -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.FullName -notmatch '\\node_modules\\|\\.git\\|\\.next\\|\\dist\\|\\build\\' } |
        Select-Object -ExpandProperty FullName |
        fzf --height 70% --border --prompt "file > "
      if ($file) { code $file }
    }

    "FILES*Generate tree.txt*" { treetxt }
    "FILES*Print tree*" { treef }

    "GIT*Status*" { git status }
    "GIT*Add all*" { git add . }
    "GIT*Commit*" {
      $msg = Read-Host "Commit message"
      if ($msg) { git commit -m $msg }
    }
    "GIT*Push*" { git push }

    "WSL*Open WSL here*" { wslhere }
    "WSL*List WSL*" { wsllist }

    "NETWORK*List listening ports*" { ports }
    "NETWORK*Check port*" {
      $p = Read-Host "Port"
      if ($p) { port ([int]$p) }
    }
    "NETWORK*Kill process by port*" {
      $p = Read-Host "Port"
      if ($p) { killport ([int]$p) }
    }
    "NETWORK*Kill process by PID*" {
      $p = Read-Host "PID"
      if ($p) { killpid ([int]$p) }
    }
    "NETWORK*Test github.com*" { netcheck github.com }
    "NETWORK*DNS github.com*" { dnscheck github.com }

    "SYSTEM*Dev rig check*" { devcheck }
    "SYSTEM*Show PATH*" { pathcheck }
    "SYSTEM*Edit PowerShell profile*" { profile }
    "SYSTEM*Reload PowerShell profile*" { reload }
  }
}

try {
  Import-Module PSFzf -ErrorAction Stop

  if (Get-Command fzf -ErrorAction SilentlyContinue) {
    if (Get-Command Set-PsFzfOption -ErrorAction SilentlyContinue) {
