$ErrorActionPreference = "Stop"

$DataPath = "_OPS/court-gesture.data.json"
$OutPath = "_OPS/Court Gesture.md"

if (!(Test-Path $DataPath)) {
  throw "Missing data file: $DataPath"
}

$data = Get-Content $DataPath -Raw | ConvertFrom-Json

if (!$data.title) { throw "Missing required field: title" }
if (!$data.sections) { throw "Missing required field: sections" }

$lines = New-Object System.Collections.Generic.List[string]

$lines.Add("# $($data.title)")
$lines.Add("")

foreach ($section in $data.sections) {
  if (!$section.title) { throw "Section missing required field: title" }

  $lines.Add("## $($section.title)")
  $lines.Add("")

  if ($section.items) {
    foreach ($item in $section.items) {
      if ($item.text) {
        $lines.Add($item.text)
        $lines.Add("")
      }

      if ($item.title) {
        $lines.Add("### $($item.title)")
        $lines.Add("")
      }

      if ($item.body) {
        $lines.Add($item.body.TrimEnd())
        $lines.Add("")
      }
    }
  }

  if ($section.body) {
    $lines.Add($section.body.TrimEnd())
    $lines.Add("")
  }

  if ($section.table) {
    $headers = $section.table.headers
    $lines.Add("| " + ($headers -join " | ") + " |")
    $lines.Add("| " + (($headers | ForEach-Object { "---" }) -join " | ") + " |")

    foreach ($row in $section.table.rows) {
      $lines.Add("| " + ($row -join " | ") + " |")
    }

    $lines.Add("")
  }
}

$outDir = Split-Path $OutPath -Parent
if (!(Test-Path $outDir)) {
  New-Item -ItemType Directory -Path $outDir | Out-Null
}

[System.IO.File]::WriteAllText(
  (Resolve-Path $outDir).Path + "\Court Gesture.md",
  ($lines -join "`r`n").TrimEnd() + "`r`n",
  [System.Text.UTF8Encoding]::new($false)
)

Write-Host "Wrote $OutPath"
