$ErrorActionPreference = "Stop"

$DataFile = "_OPS/court-gesture.data.json"
$OutputFile = "_OPS/Court Gesture.md"

function Die($msg) {
  throw "[court-gesture] $msg"
}

if (!(Test-Path $DataFile)) {
  Die "Missing JSON file: $DataFile"
}

try {
  $data = Get-Content $DataFile -Raw | ConvertFrom-Json
} catch {
  Die "Invalid JSON in $DataFile :: $($_.Exception.Message)"
}

if (!$data.title) { Die "Missing required field: title" }
if (!$data.sections) { Die "Missing required field: sections" }

$lines = New-Object System.Collections.Generic.List[string]

function Add-Line($text = "") {
  $script:lines.Add([string]$text)
}

function Add-Block($text) {
  if ($null -ne $text -and "$text".Trim().Length -gt 0) {
    foreach ($line in ("$text" -split "`n")) {
      Add-Line ($line.TrimEnd("`r"))
    }
    Add-Line
  }
}

function Require-Section($title) {
  $section = $data.sections | Where-Object { $_.title -eq $title } | Select-Object -First 1
  if (!$section) { Die "Missing required section: $title" }
  return $section
}

Add-Line "# $($data.title)"
Add-Line

# Authorities & Reference Materials
$section = Require-Section "Authorities & Reference Materials"
Add-Line "## $($section.title)"
Add-Line
foreach ($item in $section.items) {
  if ($null -eq $item.order) { Die "Authority item missing order" }
  if (!$item.markdown) { Die "Authority item $($item.order) missing markdown" }
  Add-Block "$($item.order). $($item.markdown)"
}

# Constitutional Authorities
$section = Require-Section "Constitutional Authorities"
Add-Line "### $($section.title)"
Add-Line
foreach ($item in $section.items) {
  Add-Line "- $item"
}
Add-Line

# New Mexico Supreme Court Authorities
$section = Require-Section "New Mexico Supreme Court Authorities"
Add-Line "### $($section.title)"
Add-Line
foreach ($item in $section.items) {
  Add-Line "- $item"
}
Add-Line

# Secondary Authorities
$section = Require-Section "Secondary Authorities"
Add-Line "### $($section.title)"
Add-Line
foreach ($item in $section.items) {
  Add-Line "- $item"
}
Add-Line

# Arguments
$section = Require-Section "Arguments"
Add-Line "## $($section.title)"
Add-Line
foreach ($arg in $section.arguments) {
  if (!$arg.heading) { Die "Argument missing heading" }
  if (!$arg.text) { Die "Argument $($arg.heading) missing text" }

  Add-Line "### $($arg.heading)"
  Add-Line
  Add-Block $arg.text
