### `hooks/use-copy-to-clipboard.ts`

```ts
"use client"

import { useCallback, useState } from "react"

export function useCopyToClipboard(timeoutMs = 1600) {
  const [copied, setCopied] = useState(false)

  const copy = useCallback(
    async (value: string) => {
      if (!navigator.clipboard) {
        setCopied(false)
        return false
      }

      try {
        await navigator.clipboard.writeText(value)
        setCopied(true)

        window.setTimeout(() => {
          setCopied(false)
        }, timeoutMs)

        return true
      } catch {
        setCopied(false)
        return false
      }
    },
    [timeoutMs]
  )

  return { copied, copy }
}
```

### `hooks/use-countdown.ts`

```ts
"use client"

import { useEffect, useMemo, useState } from "react"

export interface CountdownState {
  now: number
  target: number
  remainingMs: number
  isElapsed: boolean
}

export function useCountdown(targetDate: string | Date, intervalMs = 1000): CountdownState {
  const target = useMemo(() => new Date(targetDate).getTime(), [targetDate])
  const [now, setNow] = useState(() => Date.now())

  useEffect(() => {
    const timer = window.setInterval(() => {
      setNow(Date.now())
    }, intervalMs)

    return () => {
      window.clearInterval(timer)
    }
  }, [intervalMs])

  const remainingMs = Math.max(target - now, 0)

  return {
    now,
    target,
    remainingMs,
    isElapsed: remainingMs === 0,
  }
}
```

### `hooks/use-mounted.ts`

```ts
"use client"

import { useEffect, useState } from "react"

export function useMounted(): boolean {
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  return mounted
}
```

## Verdict

Add `/hooks`, but only this lean set. It supports the mocked UI without smuggling domain logic into the client bundle.
